ALTER TABLE ${primehrSchema}.spms_rating_assessment DROP CONSTRAINT ck_spms_rating_assessment_type;
ALTER TABLE ${primehrSchema}.spms_rating_assessment ADD CONSTRAINT ck_spms_rating_assessment_type CHECK(assessment_type IN ('SELF','SUPERVISOR','CALIBRATED','APPEAL_MODIFIED'));
ALTER TABLE ${primehrSchema}.spms_final_rating ADD supersedes_id VARCHAR(36);
ALTER TABLE ${primehrSchema}.spms_final_rating ADD CONSTRAINT fk_spms_final_rating_supersedes FOREIGN KEY(supersedes_id) REFERENCES ${primehrSchema}.spms_final_rating(id);
CREATE TABLE ${primehrSchema}.spms_rating_acknowledgment(id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,final_rating_id VARCHAR(36) NOT NULL,rating_case_id VARCHAR(36) NOT NULL,employee_no VARCHAR(100) NOT NULL,status VARCHAR(40) NOT NULL,employee_response VARCHAR(2000),closure_reason VARCHAR(2000),acted_by VARCHAR(100) NOT NULL,acted_at DATETIMEOFFSET NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at DATETIMEOFFSET NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at DATETIMEOFFSET NOT NULL,CONSTRAINT fk_spms_rating_ack_final FOREIGN KEY(final_rating_id) REFERENCES ${primehrSchema}.spms_final_rating(id),CONSTRAINT fk_spms_rating_ack_case FOREIGN KEY(rating_case_id) REFERENCES ${primehrSchema}.spms_rating_case(id),CONSTRAINT uk_spms_rating_ack_final UNIQUE(agency_id,final_rating_id),CONSTRAINT ck_spms_rating_ack_status CHECK(status IN ('ACKNOWLEDGED','CLOSED_WITHOUT_ACKNOWLEDGMENT')));
CREATE TABLE ${primehrSchema}.spms_rating_appeal(id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,final_rating_id VARCHAR(36) NOT NULL,rating_case_id VARCHAR(36) NOT NULL,appellant_employee_no VARCHAR(100) NOT NULL,grounds VARCHAR(4000) NOT NULL,requested_remedy VARCHAR(2000) NOT NULL,status VARCHAR(20) NOT NULL,submitted_at DATETIMEOFFSET,decided_by VARCHAR(100),decided_at DATETIMEOFFSET,decision_reason VARCHAR(4000),successor_final_rating_id VARCHAR(36),record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at DATETIMEOFFSET NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at DATETIMEOFFSET NOT NULL,CONSTRAINT fk_spms_appeal_final FOREIGN KEY(final_rating_id) REFERENCES ${primehrSchema}.spms_final_rating(id),CONSTRAINT fk_spms_appeal_case FOREIGN KEY(rating_case_id) REFERENCES ${primehrSchema}.spms_rating_case(id),CONSTRAINT fk_spms_appeal_successor FOREIGN KEY(successor_final_rating_id) REFERENCES ${primehrSchema}.spms_final_rating(id),CONSTRAINT uk_spms_appeal_final UNIQUE(agency_id,final_rating_id),CONSTRAINT ck_spms_appeal_status CHECK(status IN ('DRAFT','SUBMITTED','UPHELD','MODIFIED','REMANDED','DISMISSED')));
CREATE TABLE ${primehrSchema}.spms_rating_appeal_evidence(id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,appeal_id VARCHAR(36) NOT NULL,original_filename VARCHAR(255) NOT NULL,storage_provider VARCHAR(30) NOT NULL,storage_object_key VARCHAR(500) NOT NULL,media_type VARCHAR(120) NOT NULL,byte_size BIGINT NOT NULL,checksum VARCHAR(64) NOT NULL,uploaded_by VARCHAR(100) NOT NULL,uploaded_at DATETIMEOFFSET NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at DATETIMEOFFSET NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at DATETIMEOFFSET NOT NULL,CONSTRAINT fk_spms_appeal_evidence FOREIGN KEY(appeal_id) REFERENCES ${primehrSchema}.spms_rating_appeal(id),CONSTRAINT ck_spms_appeal_evidence_size CHECK(byte_size>0));
CREATE TABLE ${primehrSchema}.spms_intervention_rule(id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,policy_version_id VARCHAR(36) NOT NULL,rating_scale_version_id VARCHAR(36) NOT NULL,rating_band_id VARCHAR(36) NOT NULL,intervention_action VARCHAR(30) NOT NULL,employee_message VARCHAR(2000),created_by_rule VARCHAR(100) NOT NULL,created_at_rule DATETIMEOFFSET NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at DATETIMEOFFSET NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at DATETIMEOFFSET NOT NULL,CONSTRAINT fk_spms_intervention_policy FOREIGN KEY(policy_version_id) REFERENCES ${primehrSchema}.spms_policy_version(id),CONSTRAINT fk_spms_intervention_scale FOREIGN KEY(rating_scale_version_id) REFERENCES ${primehrSchema}.spms_rating_scale_version(id),CONSTRAINT fk_spms_intervention_band FOREIGN KEY(rating_band_id) REFERENCES ${primehrSchema}.spms_rating_band(id),CONSTRAINT uk_spms_intervention_exact_band UNIQUE(agency_id,policy_version_id,rating_scale_version_id,rating_band_id),CONSTRAINT ck_spms_intervention_action CHECK(intervention_action IN ('NONE','ALERT','PIP_RECOMMENDED','PIP_REQUIRED')));
CREATE TABLE ${primehrSchema}.spms_performance_intervention(id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,final_rating_id VARCHAR(36) NOT NULL,rating_case_id VARCHAR(36) NOT NULL,rule_id VARCHAR(36) NOT NULL,employee_no VARCHAR(100) NOT NULL,intervention_action VARCHAR(30) NOT NULL,status VARCHAR(20) NOT NULL,objectives VARCHAR(4000),support_plan VARCHAR(4000),accountable_employee_no VARCHAR(100),starts_on DATE,ends_on DATE,employee_response VARCHAR(2000),issued_by VARCHAR(100),issued_at DATETIMEOFFSET,acknowledged_at DATETIMEOFFSET,completed_at DATETIMEOFFSET,closed_at DATETIMEOFFSET,closure_reason VARCHAR(2000),record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at DATETIMEOFFSET NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at DATETIMEOFFSET NOT NULL,CONSTRAINT fk_spms_perf_intervention_final FOREIGN KEY(final_rating_id) REFERENCES ${primehrSchema}.spms_final_rating(id),CONSTRAINT fk_spms_perf_intervention_case FOREIGN KEY(rating_case_id) REFERENCES ${primehrSchema}.spms_rating_case(id),CONSTRAINT fk_spms_perf_intervention_rule FOREIGN KEY(rule_id) REFERENCES ${primehrSchema}.spms_intervention_rule(id),CONSTRAINT uk_spms_intervention_final UNIQUE(agency_id,final_rating_id),CONSTRAINT ck_spms_perf_intervention_action CHECK(intervention_action IN ('ALERT','PIP_RECOMMENDED','PIP_REQUIRED')),CONSTRAINT ck_spms_perf_intervention_status CHECK(status IN ('OPEN','ISSUED','ACKNOWLEDGED','IN_PROGRESS','COMPLETED','CLOSED')));
CREATE TABLE ${primehrSchema}.spms_intervention_checkpoint(id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,intervention_id VARCHAR(36) NOT NULL,due_on DATE NOT NULL,objective VARCHAR(2000) NOT NULL,progress_note VARCHAR(4000),employee_visible_feedback VARCHAR(4000),private_pmt_note VARCHAR(4000),status VARCHAR(20) NOT NULL,completed_by VARCHAR(100),completed_at DATETIMEOFFSET,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at DATETIMEOFFSET NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at DATETIMEOFFSET NOT NULL,CONSTRAINT fk_spms_checkpoint_intervention FOREIGN KEY(intervention_id) REFERENCES ${primehrSchema}.spms_performance_intervention(id),CONSTRAINT uk_spms_checkpoint_due UNIQUE(agency_id,intervention_id,due_on),CONSTRAINT ck_spms_checkpoint_status CHECK(status IN ('PLANNED','COMPLETED','VERIFIED')));
CREATE INDEX ix_spms_appeal_status ON ${primehrSchema}.spms_rating_appeal(agency_id,status);
CREATE INDEX ix_spms_intervention_status ON ${primehrSchema}.spms_performance_intervention(agency_id,status);
